content:
MIME-Version: 1.0
Content-Type: multipart/mixed; boundary="ptf-boundary-noteimg1"

--ptf-boundary-noteimg1
Content-Type: text/x-vue; charset=utf-8
Content-Disposition: attachment; filename="fluid.demos.closestNoteImageGen"
Content-Description: layer

<script>
// Combines the closest-note finder with the image generator: the finder (top) watches the notes on the canvas and
// its closest note's text feeds the generator's prompt (bottom), so moving the widget next to a sticky note and
// pressing its button generates an image from that note.

fluid.def("fluid.demos.closestNoteImageGen", {
    $layers: "fluid.topLevelWidget",
    preferredSize: {
        w: 360,
        h: 680
    },
    noteFinder: {
        $component: {
            $layers: "fluid.demos.closestNoteFinder",
            // Forward the hosting context from this umbrella widget down into the nested finder
            hostBounds: "{self}.hostBounds",
            tldrawHost: "{tldrawHost}"
        }
    },
    imageGenerator: {
        $component: {
            $layers: "fluid.demos.imageGenerator",
            // The generator's prompt now tracks the closest note; it can still be edited by typing
            state: {
                prompt: "{noteFinder}.noteText"
            }
        }
    }
});
</script>

<template>
    <div class="noteimg">
        <div @id="noteFinder" class="noteimg-finder"></div>
        <div class="noteimg-gap"></div>
        <div @id="imageGenerator" class="noteimg-generator"></div>
    </div>
</template>

<style>
.noteimg {
    width: 100%;
    height: 100%;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    background-color: #fffbea;
    border: 1px solid #f0e4c0;
    border-radius: 6px;
    overflow: hidden;
}

.noteimg-finder {
    flex: 0 0 200px;
}

.noteimg-gap {
    flex: 0 0 8px;
}

.noteimg-generator {
    flex: 1 1 auto;
    min-height: 0;
}
</style>
--ptf-boundary-noteimg1
Content-Type: multipart/mixed; boundary="ptf-boundary-noteimg2"
Content-Disposition: attachment; filename="shape:imagegen"
Content-Description: component

--ptf-boundary-noteimg2
Content-Type: application/json; charset=utf-8
Content-Disposition: attachment; filename="/"
Content-Description: potentia

{
    "$layers": [
        "fluid.demos.closestNoteImageGen"
    ],
    "view": {
        "$component": {
            "shapeId": "shape:imagegen"
        }
    }
}
--ptf-boundary-noteimg2
Content-Type: application/json; charset=utf-8
Content-Disposition: attachment; filename="shape"
Content-Description: shape

{"x": 420, "y": 100, "w": 360, "h": 680}
--ptf-boundary-noteimg2--
--ptf-boundary-noteimg1
Content-Type: text/plain; charset=utf-8
Content-Disposition: attachment; filename="shape:finder"
Content-Description: delete

--ptf-boundary-noteimg1--

